const TREND_METRICS={accuracy:{label:'Accuracy',color:'#1677ff',value:point=>point.accuracy,suffix:'%',scale:points=>({min:0,max:100})},score:{label:'Marks obtained',color:'#8448b7',value:point=>point.score,suffix:'',scale:points=>({min:Math.min(0,...points.map(point=>point.score)),max:Math.max(1,...points.map(point=>point.maxScore||point.score))})},correct:{label:'Correct questions',color:'#169b52',value:point=>point.correct,suffix:'',scale:countScale},wrong:{label:'Wrong questions',color:'#d84040',value:point=>point.wrong,suffix:'',scale:countScale},skipped:{label:'Skipped questions',color:'#ee8a24',value:point=>point.skipped,suffix:'',scale:countScale}};
function countScale(points){return{min:0,max:Math.max(1,...points.map(point=>point.correct+point.wrong+point.skipped))};}
let trendChartSeq=0;
function smoothTrendPath(coords){if(coords.length===1)return`M${coords[0][0].toFixed(1)},${coords[0][1].toFixed(1)}`;let d=`M${coords[0][0].toFixed(1)},${coords[0][1].toFixed(1)}`;for(let i=0;i<coords.length-1;i++){const p0=coords[Math.max(0,i-1)],p1=coords[i],p2=coords[i+1],p3=coords[Math.min(coords.length-1,i+2)];const c1x=p1[0]+(p2[0]-p0[0])/6,c1y=p1[1]+(p2[1]-p0[1])/6;const c2x=p2[0]-(p3[0]-p1[0])/6,c2y=p2[1]-(p3[1]-p1[1])/6;d+=`C${c1x.toFixed(1)},${c1y.toFixed(1)} ${c2x.toFixed(1)},${c2y.toFixed(1)} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;}return d;}
function trendChart(points,metricKey,compact=false){const metric=TREND_METRICS[metricKey];if(!points.length)return'<div class="empty">Complete a subject test to start your trend.</div>';const recent=points.slice(-12),width=compact?520:760,height=compact?190:230,left=48,right=20,top=20,bottom=38;const scale=metric.scale(recent),range=Math.max(1,scale.max-scale.min);const x=index=>recent.length===1?(left+width-right)/2:left+(index*(width-left-right)/(recent.length-1));const y=value=>top+((scale.max-value)*(height-top-bottom)/range);const coords=recent.map((point,index)=>[x(index),y(metric.value(point))]);const linePath=smoothTrendPath(coords);const baseY=y(scale.min);const areaPath=coords.length>1?`${linePath}L${coords[coords.length-1][0].toFixed(1)},${baseY.toFixed(1)}L${coords[0][0].toFixed(1)},${baseY.toFixed(1)}Z`:'';const ticks=[0,.25,.5,.75,1].map(fraction=>scale.min+range*fraction);const format=value=>metricKey==='score'?Number(value.toFixed(2)):Math.round(value);const latest=metric.value(recent.at(-1));const gid=`trend-area-${metricKey}-${trendChartSeq++}`;return`<article class="metric-chart-card ${compact?'compact':''}" style="--metric-color:${metric.color}"><header><div><b>${metric.label}</b><small>${recent.length} attempt${recent.length===1?'':'s'}</small></div><strong>${format(latest)}${metric.suffix}</strong></header><div class="trend-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${metric.label} trend over ${recent.length} attempts"><defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${metric.color}" stop-opacity=".22"/><stop offset="1" stop-color="${metric.color}" stop-opacity="0"/></linearGradient></defs>${ticks.map(value=>`<line x1="${left}" y1="${y(value)}" x2="${width-right}" y2="${y(value)}" class="trend-grid"/><text x="${left-9}" y="${y(value)+4}" text-anchor="end">${format(value)}${metric.suffix}</text>`).join('')}${areaPath?`<path d="${areaPath}" fill="url(#${gid})" class="trend-area"/>`:''}<path d="${linePath}" class="trend-line" fill="none"/>${recent.map((point,index)=>`<circle cx="${x(index)}" cy="${y(metric.value(point))}" r="5" class="trend-dot${index===recent.length-1?' latest':''}"><title>${escapeHTML(point.title)}: ${format(metric.value(point))}${metric.suffix}</title></circle><text x="${x(index)}" y="${height-10}" text-anchor="middle" class="trend-xlabel">${index+1}</text>`).join('')}</svg></div></article>`;}
function renderSubjectTrend(subject){const target=document.querySelector('#trend-panel');if(!target)return;const trend=buildSubjectTrends(attempts).find(item=>item.subject===subject);const points=trend?.points||[];const summary=summarizeSubjectTrend(points);const change=summary.accuracyChange;const metricKeys=Object.keys(TREND_METRICS);const charts=trendMetricView==='all'?metricKeys.map(key=>trendChart(points,key,true)).join(''):trendChart(points,trendMetricView);target.innerHTML=`<div class="trend-metrics"><div><small>Latest accuracy</small><b>${summary.latestAccuracy}%</b></div><div><small>Change from previous</small><b class="${change>0?'ok':change<0?'bad':''}">${change>0?'+':''}${change}%</b></div><div class="time-metric correct"><small>Avg time · correct</small><b>${summary.latestAverageCorrectSeconds}s</b></div><div class="time-metric wrong"><small>Avg time · wrong</small><b>${summary.latestAverageWrongSeconds}s</b></div><div class="time-metric skipped"><small>Avg time · skipped</small><b>${summary.latestAverageSkippedSeconds}s</b></div><div><small>Subject attempts</small><b>${summary.attempts}</b></div></div><p class="trend-note">Skipped time includes 0 seconds for questions you never opened. If you opened a question and left it unanswered, the time you spent is included.</p><div class="trend-switcher"><button data-trend-metric="all" aria-pressed="${trendMetricView==='all'}" class="${trendMetricView==='all'?'active':''}">All graphs</button>${metricKeys.map(key=>`<button data-trend-metric="${key}" aria-pressed="${trendMetricView===key}" class="${trendMetricView===key?'active':''}" style="--metric-color:${TREND_METRICS[key].color}"><i></i>${TREND_METRICS[key].label}</button>`).join('')}</div><div class="trend-visuals ${trendMetricView==='all'?'all':''}">${charts}</div>${points.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Attempt</th><th>Marks</th><th>Accuracy</th><th>Correct / Wrong / Skipped</th><th>Avg correct</th><th>Avg wrong</th><th>Avg skipped</th><th>Date</th></tr></thead><tbody>${[...points].reverse().slice(0,8).map(point=>`<tr><td>${escapeHTML(point.title)}</td><td><b>${point.score}/${point.maxScore}</b></td><td><b>${point.accuracy}%</b></td><td>${point.correct} / ${point.wrong} / ${point.skipped}</td><td class="ok">${point.averageCorrectSeconds}s</td><td class="bad">${point.averageWrongSeconds}s</td><td class="skip">${point.averageSkippedSeconds}s</td><td>${new Date(point.completedAt).toLocaleDateString()}</td></tr>`).join('')}</tbody></table></div>`:''}`;target.querySelectorAll('[data-trend-metric]').forEach(button=>button.addEventListener('click',()=>{trendMetricView=button.dataset.trendMetric;renderSubjectTrend(subject);}));}
function renderHistory(){const genuine=attempts.filter(a=>!a.isTestRun);const summary=analyticsSummary();const trends=buildSubjectTrends(attempts);const defaultSubject=trends.find(item=>item.subject==='Quantitative Aptitude')?.subject||trends[0]?.subject||'';shell('History',`<section class="metric-grid"><div class="metric"><small>Total attempts</small><b>${attempts.length}</b></div><div class="metric"><small>Genuine attempts</small><b>${genuine.length}</b></div><div class="metric"><small>Objective accuracy</small><b>${summary.accuracy}%</b></div><div class="metric"><small>Active practice</small><b>${formatTime(summary.active)}</b></div></section><section class="card trend-card"><div class="card-head"><div><h2>Subject performance trend</h2><small class="muted">Track accuracy plus separate correct, wrong and skipped-question timing.</small></div><select class="input" id="trend-subject">${trends.length?trends.map(item=>`<option ${item.subject===defaultSubject?'selected':''}>${escapeHTML(item.subject)}</option>`).join(''):'<option value="">No subject data yet</option>'}</select></div><div class="card-body" id="trend-panel"></div></section><section class="card" style="margin-top:16px"><div class="card-head"><h2>Attempt history</h2><div><button class="btn small" data-action="export-history">Export</button> <button class="btn small danger" data-action="clear-history">Delete all</button></div></div><div class="card-body">${attempts.length?attemptTable(attempts):'<div class="empty">No attempts saved.</div>'}</div></section>`);bindAttemptLinks();renderSubjectTrend(defaultSubject);document.querySelector('#trend-subject').addEventListener('change',event=>renderSubjectTrend(event.target.value));document.querySelector('[data-action="export-history"]').addEventListener('click',()=>downloadJSON('attempt-history.json',{attempts}));document.querySelector('[data-action="clear-history"]').addEventListener('click',()=>{if(confirm('Permanently delete all local attempt history?')){attempts=[];storage.clearAttempts();renderHistory();}});}

function openAttempt(id){const attempt=attempts.find(a=>a.id===id);if(!attempt)return;currentAttempt=attempt;reviewQuestionIndex=0;renderAttemptReview();}
function attemptReviewRows(){return currentAttempt?.analytics?.rows||[];}
function attemptReviewSections(){return unique(attemptReviewRows().map(row=>row.question.section||row.question.subject));}
function attemptReviewIndices(section){return attemptReviewRows().map((row,index)=>(row.question.section||row.question.subject)===section?index:-1).filter(index=>index>=0);}
function reviewAIChat(attempt=currentAttempt){const key=reviewChatKey(attempt?.id);let chat=tutorChats.find(item=>item.contextKey===key)||null;if(chat)return chat;const legacyPrefix=`review:${attempt?.id}:`;const legacy=tutorChats.filter(item=>item.contextKey?.startsWith(legacyPrefix));if(!legacy.length)return null;const rows=(attempt?.analytics?.rows||[]);const messages=legacy.flatMap(item=>{const questionId=item.contextKey.slice(legacyPrefix.length);const row=rows.find(candidate=>candidate.question.id===questionId);return item.messages.map(message=>({...message,questionId,questionNumber:row?.index+1,topic:row?.question.topic}));}).sort((a,b)=>new Date(a.createdAt||0)-new Date(b.createdAt||0));chat={id:uid('chat'),contextKey:key,title:reviewChatTitle(attempt),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),messages,analysedQuestionIds:legacy.map(item=>item.contextKey.slice(legacyPrefix.length)),questionMemories:[],attemptContextSent:true};tutorChats=[chat,...tutorChats.filter(item=>!legacy.includes(item))].slice(0,40);storage.saveTutorChats(tutorChats);return chat;}
function saveReviewAIChat(changes={},attempt=currentAttempt){const now=new Date().toISOString();const key=reviewChatKey(attempt.id);const existing=reviewAIChat(attempt);const chat={...(existing||{id:uid('chat'),contextKey:key,title:reviewChatTitle(attempt),createdAt:now,messages:[],analysedQuestionIds:[],questionMemories:[],attemptContextSent:false}),...changes,contextKey:key,title:reviewChatTitle(attempt),updatedAt:now};chat.messages=chat.messages||[];chat.analysedQuestionIds=[...new Set(chat.analysedQuestionIds||[])];chat.questionMemories=(chat.questionMemories||[]).slice(-50);tutorChats=[chat,...tutorChats.filter(item=>item.id!==chat.id)].slice(0,40);storage.saveTutorChats(tutorChats);return chat;}
function questionAlreadyAnalysed(row){return Boolean(reviewAIChat()?.analysedQuestionIds?.includes(row.question.id));}
function renderReviewAIPanel(row){
  const panel=document.querySelector('#review-ai-panel');if(!panel)return;
  const chat=reviewAIChat();const messages=chat?.messages||[];const connected=tutorConnected();const analysed=questionAlreadyAnalysed(row);
  const messageHTML=messages.map(message=>`<div class="review-ai-turn"><span class="review-chat-avatar ${message.role==='user'?'user':'assistant'}">${message.role==='user'?'You':'AI'}</span><div class="review-ai-message ${message.role==='user'?'user':'assistant'}" data-chat-question="${Number(message.questionNumber)||''}"><div class="review-message-label">Question ${message.questionNumber||'?'} · ${escapeHTML(message.topic||'Review')}</div><div>${message.role==='assistant'?renderMarkdown(message.content):escapeHTML(message.content).replace(/\n/g,'<br>')}</div><small>${message.role==='user'?'You':'AI Coach'} · ${new Date(message.createdAt||Date.now()).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('');
  const startControl=connected?(reviewAILoading?'':'<button class="btn primary" data-action="start-review-ai">Analyse this question</button>'):'<button class="btn primary" data-action="open-ai-settings">Open AI connection</button>';
  const emptyHTML=`<div class="review-ai-empty"><b>${connected?'Ready to analyse this mock':'Connect an AI model to analyse questions.'}</b><p>${connected?'The first question sends the full attempt once. Later questions reuse a smaller saved context.':'Your question and mock data remain available until a model is connected.'}</p>${startControl}</div>`;
  const loadingHTML=reviewAILoading?`<div class="review-ai-turn typing-turn"><span class="review-chat-avatar assistant">AI</span><div class="review-ai-message assistant typing-message"><div class="review-message-label">Question ${reviewAILoadingQuestion} · analysing</div><div class="typing-copy">The coach is reading your answer and timing<span class="typing-dots"><i></i><i></i><i></i></span></div></div></div>`:'';
  const composeHTML=connected?`<div class="review-ai-compose"><div class="review-ai-quick"><button data-review-quick="Why is my method wrong?">Why was my method wrong?</button><button data-review-quick="Show the fastest safe method for this question.">Faster method</button><button data-review-quick="Was my time reasonable for this question?">Check my time</button><button data-review-quick="Does this mistake match a pattern from the other questions we reviewed?">Find a pattern</button></div><textarea id="review-ai-input" rows="3" placeholder="Ask about Question ${row.index+1}…" ${reviewAILoading?'disabled':''}></textarea><div><span id="review-ai-status" class="status ${reviewAIError?'bad':''}">${escapeHTML(reviewAIError)}</span><button class="btn primary" data-action="send-review-ai" ${reviewAILoading?'disabled':''}>Send</button></div></div>`:'';
  panel.innerHTML=`<header><div class="review-coach-identity"><span class="review-coach-avatar">AI</span><div><b>Mock Review Coach</b><small><i class="connection-dot ${connected?'online':''}"></i> ${connected?escapeHTML(activeProfile()?.name||aiConfig.model):'Not connected'} · persistent session</small></div></div><div>${messages.length?'<button class="btn small" data-action="clear-review-ai">Clear session</button>':''}<button class="btn small" data-action="close-review-ai">Close</button></div></header><div class="review-ai-focus"><b>Looking at Question ${row.index+1}</b><span>${escapeHTML(row.question.topic)} · ${escapeHTML(reviewStatus(row.status).label)} · ${formatReviewDuration(row.activeSeconds)}</span>${analysed?'<em>Already analysed — no new API request</em>':''}</div><div class="review-ai-messages" id="review-ai-messages">${messageHTML||emptyHTML}${loadingHTML}</div>${composeHTML}`;
  bindReviewAIPanel(row);setTimeout(()=>{const box=document.querySelector('#review-ai-messages');const matches=[...document.querySelectorAll(`[data-chat-question="${row.index+1}"]`)];if(analysed&&matches.length)matches.at(-1).scrollIntoView({block:'center'});else if(box)box.scrollTop=box.scrollHeight;},0);
}
function bindReviewAIPanel(row){document.querySelectorAll('[data-action="close-review-ai"]').forEach(button=>button.addEventListener('click',closeReviewAI));document.querySelector('[data-action="open-ai-settings"]')?.addEventListener('click',()=>navigate('ai'));document.querySelector('[data-action="start-review-ai"]')?.addEventListener('click',()=>runReviewAI(row,'',true));document.querySelector('[data-action="clear-review-ai"]')?.addEventListener('click',()=>{if(reviewAIRequest)return showToast('Wait for the reply before clearing this session.','warn');if(!confirm('Clear the saved AI coaching session for this mock?'))return;const chat=reviewAIChat();if(chat)tutorChats=tutorChats.filter(item=>item.id!==chat.id);storage.saveTutorChats(tutorChats);reviewAIError='';renderReviewAIPanel(row);});document.querySelector('[data-action="send-review-ai"]')?.addEventListener('click',()=>{const input=document.querySelector('#review-ai-input');runReviewAI(row,input.value.trim(),false);});document.querySelector('#review-ai-input')?.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();runReviewAI(row,event.currentTarget.value.trim(),false);}});document.querySelectorAll('[data-review-quick]').forEach(button=>button.addEventListener('click',()=>{const input=document.querySelector('#review-ai-input');input.value=button.dataset.reviewQuick;input.focus();}));}
function openReviewAI(){const row=attemptReviewRows()[reviewQuestionIndex];if(!row)return;reviewAIError='';document.querySelector('#review-ai-shade').classList.remove('hidden');document.querySelector('#review-ai-panel').classList.remove('hidden');renderReviewAIPanel(row);if(tutorConnected()&&!questionAlreadyAnalysed(row)&&!reviewAILoading)runReviewAI(row,'',true);}
function closeReviewAI(){document.querySelector('#review-ai-shade')?.classList.add('hidden');document.querySelector('#review-ai-panel')?.classList.add('hidden');}
async function runReviewAI(row,message,initial=false){
  if(reviewAIRequest)return;
  if(!tutorConnected()){renderReviewAIPanel(row);return;}
  const attempt=currentAttempt;const chat=reviewAIChat(attempt);
  if(initial&&chat?.analysedQuestionIds?.includes(row.question.id)){renderReviewAIPanel(row);return;}
  if(!initial&&!message)return;
  const packet=buildCoachPacket(attempt,attempt.analytics);
  const selectedResponse=packet.responses.find(item=>Number(item.number)===Number(row.index+1));
  let messages=[...(chat?.messages||[])];
  if(!initial)messages.push({role:'user',content:message,createdAt:new Date().toISOString(),questionId:row.question.id,questionNumber:row.index+1,topic:row.question.topic});
  const saved=saveReviewAIChat({messages},attempt);const chatId=saved.id;
  reviewAIRequest={attemptId:attempt.id,chatId};reviewAILoading=true;reviewAILoadingQuestion=row.index+1;reviewAIError='';renderReviewAIPanel(row);
  try{
    const prompt=buildQuestionCoachPrompt({attemptPacket:packet,questionNumber:row.index+1,history:chat?.messages||[],userMessage:initial?'':message,includeFullAttempt:!chat?.attemptContextSent,questionMemories:chat?.questionMemories||[]});
    const response=await callAI({config:{...aiConfig},apiKey:sessionApiKey,prompt});
    const latest=tutorChats.find(item=>item.id===chatId);
    if(latest){
      messages=[...latest.messages,{role:'assistant',content:response,createdAt:new Date().toISOString(),questionId:row.question.id,questionNumber:row.index+1,topic:row.question.topic}];
      const memory=buildQuestionMemory(selectedResponse,response);
      saveReviewAIChat({messages,questionMemories:[...(latest.questionMemories||[]).filter(item=>item.questionId!==row.question.id),memory],analysedQuestionIds:[...(latest.analysedQuestionIds||[]),row.question.id],attemptContextSent:true},attempt);
    }
  }catch(error){reviewAIError=error.message;}
  finally{
    reviewAIRequest=null;reviewAILoading=false;
    const visibleRow=attemptReviewRows()[reviewQuestionIndex];
    if(visibleRow&&document.querySelector('#review-ai-panel'))renderReviewAIPanel(visibleRow);
  }
}

function renderAttemptReview(){
  const rows=attemptReviewRows();
  const row=rows[reviewQuestionIndex];
  if(!row)return renderAttempt();
  const q=row.question;
  const result=reviewStatus(row.status);
  const section=q.section||q.subject;
  const indices=attemptReviewIndices(section);
  const tabs=attemptReviewSections().map(name=>`<button class="section-tab ${name===section?'active':''}" data-review-section="${escapeHTML(name)}">${escapeHTML(name)}</button>`).join('');
  const palette=indices.map(index=>{const item=rows[index];const status=reviewStatus(item.status);return`<button class="qn review-${status.tone} ${index===reviewQuestionIndex?'current':''}" data-review-question="${index}" title="Question ${index+1}: ${status.label}">${index+1}</button>`;}).join('');
  let response='';
  if(q.type==='descriptive'){
    response=`<div class="review-written"><h3>Your response</h3><div>${escapeHTML(row.selected||'No response submitted.').replace(/\n/g,'<br>')}</div></div>${row.grade?.feedback?`<div class="review-explanation"><b>Grader feedback</b><p>${escapeHTML(row.grade.feedback)}</p></div>`:''}${q.modelAnswer?`<div class="review-explanation"><b>Model answer / key points</b><p>${escapeHTML(q.modelAnswer)}</p></div>`:''}`;
  }else{
    response=`<div class="review-options">${q.options.map((option,index)=>{const state=reviewOptionState(q,row.selected,index);return`<div class="review-option ${state.className}"><span class="review-radio">${state.chosen?'●':'○'}</span><span><b>${String.fromCharCode(65+index)}.</b> ${escapeHTML(option)}</span>${state.label?`<em>${escapeHTML(state.label)}</em>`:''}</div>`;}).join('')}</div><div class="answer-summary"><span>Your answer: <b>${row.selected===undefined||row.selected===null?'Not answered':`${String.fromCharCode(65+Number(row.selected))}. ${escapeHTML(q.options[row.selected]||'')}`}</b></span><span>Correct answer: <b>${String.fromCharCode(65+Number(q.answer))}. ${escapeHTML(q.options[q.answer]||'')}</b></span></div>${q.explanation?`<div class="review-explanation"><b>Explanation</b><p>${escapeHTML(q.explanation).replace(/\n/g,'<br>')}</p></div>`:''}`;
  }
  const counts=rows.reduce((acc,item)=>{acc[reviewStatus(item.status).tone]+=1;return acc;},{correct:0,wrong:0,skipped:0,pending:0});
  document.body.classList.remove('tutor-view');
  app.innerHTML=`<main class="cbt review-cbt"><header class="cbt-head"><div class="exam-title"><div class="exam-seal">✓</div><div><b>${escapeHTML(currentAttempt.title)}</b><small>Completed mock review · ${new Date(currentAttempt.completedAt).toLocaleString()}</small></div></div><div class="clock review-clock"><span>Time on this question</span><strong>${formatReviewDuration(row.activeSeconds)}</strong></div></header><nav class="section-tabs">${tabs}</nav><div class="workspace"><section class="question-pane"><div class="q-meta review-meta"><b>Question No. ${reviewQuestionIndex+1}</b><span class="review-status ${result.tone}">${escapeHTML(result.label)}</span><button class="review-ai-button" data-action="open-review-ai">Ask AI about this question</button><span>Marks awarded: <b>${Number(row.awardedMarks)||0}</b> / ${Number(q.marks)||0}</span><span>${escapeHTML(q.subject)} · ${escapeHTML(q.topic)}</span></div><div class="q-content">${renderQuestionMedia(q,true)}<div class="question-text">${escapeHTML(q.question)}</div>${response}</div><div class="exam-actions review-actions"><button class="btn" data-review-prev ${reviewQuestionIndex===0?'disabled':''}>Previous</button><div class="review-telemetry"><span>Active time <b>${formatReviewDuration(row.activeSeconds)}</b></span><span>Visits <b>${Number(row.visits)||0}</b></span><span>Answer changes <b>${Number(row.answerChanges)||0}</b></span>${row.marked?'<span>Marked for review</span>':''}</div><button class="btn primary" data-review-next ${reviewQuestionIndex===rows.length-1?'disabled':''}>Next</button></div></section><aside class="side"><div class="review-score"><small>Final score</small><b>${Number(currentAttempt.analytics.score)||0} / ${Number(currentAttempt.analytics.maxScore??currentAttempt.analytics.total)||0}</b><span>${Number(currentAttempt.analytics.accuracy)||0}% accuracy</span></div><div class="palette-head">Answer Review</div><div class="palette-body"><h4>${escapeHTML(section)}</h4><div class="q-grid">${palette}</div><div class="review-legend"><span><i class="correct"></i>Correct (${counts.correct})</span><span><i class="wrong"></i>Incorrect (${counts.wrong})</span><span><i class="skipped"></i>Skipped (${counts.skipped})</span>${counts.pending?`<span><i class="pending"></i>Pending (${counts.pending})</span>`:''}</div></div></aside></div><footer class="exam-foot"><div class="button-group"><button class="btn small" data-action="review-summary">Results summary</button><button class="btn small" data-view="history">Back to History</button></div><span class="muted">Responses are read-only in review mode.</span></footer></main><div id="review-ai-shade" class="review-ai-shade hidden" data-action="close-review-ai"></div><aside id="review-ai-panel" class="review-ai-panel hidden"></aside>`;
  bindAttemptReview();
}
function bindAttemptReview(){document.querySelectorAll('[data-review-question]').forEach(button=>button.addEventListener('click',()=>{reviewQuestionIndex=Number(button.dataset.reviewQuestion);renderAttemptReview();}));document.querySelectorAll('[data-review-section]').forEach(button=>button.addEventListener('click',()=>{reviewQuestionIndex=attemptReviewIndices(button.dataset.reviewSection)[0];renderAttemptReview();}));document.querySelector('[data-review-prev]').addEventListener('click',()=>{reviewQuestionIndex=Math.max(0,reviewQuestionIndex-1);renderAttemptReview();});document.querySelector('[data-review-next]').addEventListener('click',()=>{reviewQuestionIndex=Math.min(attemptReviewRows().length-1,reviewQuestionIndex+1);renderAttemptReview();});document.querySelector('[data-action="open-review-ai"]').addEventListener('click',openReviewAI);document.querySelector('[data-action="review-summary"]').addEventListener('click',renderAttempt);document.querySelector('[data-view="history"]').addEventListener('click',()=>navigate('history'));}

function renderAttempt(){const a=currentAttempt;const an=a.analytics;if(!an)return showToast('This legacy attempt has incomplete analytics.','warn');view='history';shell('Attempt Review',`<div class="results-head"><div><h2>${escapeHTML(a.title)}</h2><span class="muted">${new Date(a.completedAt).toLocaleString()} · elapsed ${formatTime(a.elapsedSeconds)} · active ${formatTime(an.totalActiveSeconds)}</span></div><div class="score-big"><b>${an.score}</b> / ${an.maxScore??an.total}</div></div><section class="stats"><div class="stat"><small>Correct</small><b class="ok">${an.correct}</b></div><div class="stat"><small>Wrong</small><b class="bad">${an.wrong}</b></div><div class="stat"><small>Skipped</small><b class="skip">${an.skipped}</b></div><div class="stat"><small>Accuracy</small><b>${an.accuracy}%</b></div><div class="stat"><small>Descriptive pending</small><b class="pending">${an.descriptivePending||0}</b></div></section><section class="insights"><b>Offline coaching</b>${coachInsights(an).map(x=>`<div class="insight">• ${escapeHTML(x)}</div>`).join('')}<div class="toolbar" style="margin-top:10px"><button class="btn primary" data-action="review-answers">Review answers</button><label><input id="attempt-test-run" type="checkbox" ${a.isTestRun?'checked':''}> UI test</label><button class="btn primary" data-action="copy-coach">Copy AI coaching prompt</button><button class="btn" data-action="download-attempt">Download packet</button></div><span id="attempt-status" class="status"></span></section><div class="table-wrap"><table class="table"><thead><tr><th>Q</th><th>Type</th><th>Topic</th><th>Status</th><th>Response / key</th><th>Time</th><th>Visits</th><th></th></tr></thead><tbody>${an.rows.map(row=>`<tr><td>${row.index+1}</td><td>${escapeHTML(row.question.type||'mcq')}</td><td>${escapeHTML(row.question.topic)}</td><td class="${statusClass(row.status)}">${escapeHTML(row.status)}</td><td>${row.question.type==='descriptive'?`${wordCount(row.selected)} words`: `${row.selected===undefined?'—':String.fromCharCode(65+Number(row.selected))} / ${String.fromCharCode(65+Number(row.question.answer))}`}</td><td>${row.activeSeconds}s</td><td>${row.visits}</td><td>${row.question.type==='descriptive'&&row.status!=='Skipped'?`<button class="btn small" data-grade="${row.index}">Grade</button>`:''}</td></tr>`).join('')}</tbody></table></div><section class="card" style="margin-top:16px"><div class="card-head"><h2>Saved AI feedback</h2></div><div class="card-body"><textarea id="attempt-notes" class="feedback">${escapeHTML(a.aiNotes||'')}</textarea><button class="btn primary" data-action="save-attempt-notes" style="margin-top:8px">Save feedback</button></div></section><button class="btn" data-view="history" style="margin-top:15px">Back to History</button>`);bindAttemptView();}
function bindAttemptView(){document.querySelector('[data-action="review-answers"]').addEventListener('click',()=>{reviewQuestionIndex=0;renderAttemptReview();});document.querySelector('#attempt-test-run').addEventListener('change',(e)=>updateAttempt({isTestRun:e.target.checked}));document.querySelector('[data-action="copy-coach"]').addEventListener('click',copyAttemptPrompt);document.querySelector('[data-action="download-attempt"]').addEventListener('click',()=>downloadJSON(`attempt-${currentAttempt.id}.json`,buildCoachPacket(currentAttempt,currentAttempt.analytics)));document.querySelector('[data-action="save-attempt-notes"]').addEventListener('click',()=>{updateAttempt({aiNotes:document.querySelector('#attempt-notes').value});showToast('Feedback saved.','good');});document.querySelectorAll('[data-grade]').forEach(b=>b.addEventListener('click',()=>showGradeModal(Number(b.dataset.grade))));}
function updateAttempt(changes){Object.assign(currentAttempt,changes);attempts=attempts.map(a=>a.id===currentAttempt.id?currentAttempt:a);storage.saveAttempts(attempts);}
async function copyAttemptPrompt(){const status=document.querySelector('#attempt-status');if(currentAttempt.isTestRun){status.textContent='This attempt is marked as a UI test; no coaching prompt was created.';return;}try{await copyText(buildCoachPrompt(buildCoachPacket(currentAttempt,currentAttempt.analytics)));status.textContent='Prompt copied. Paste it into any model.';}catch{status.textContent='Clipboard failed. Download the packet instead.';}}
function showGradeModal(index){const row=currentAttempt.analytics.rows[index];openModal(`<div class="modal-head"><span>Grade descriptive response</span><button class="btn small" data-close>Close</button></div><div class="modal-body"><p><b>${escapeHTML(row.question.question)}</b></p><div class="notice">Maximum marks: ${row.question.marks}. Word count: ${wordCount(row.selected)}.</div><p style="white-space:pre-wrap">${escapeHTML(row.selected)}</p><div class="field"><label>Marks awarded</label><input id="grade-score" type="number" min="0" max="${row.question.marks}" step="0.5" value="${row.grade?.score||0}"></div><div class="field"><label>Feedback</label><textarea id="grade-feedback">${escapeHTML(row.grade?.feedback||'')}</textarea></div></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn primary" id="save-grade">Save grade</button></div>`);document.querySelector('#save-grade').addEventListener('click',()=>{const grades={...(currentAttempt.grades||{}),[index]:{score:Number(document.querySelector('#grade-score').value),feedback:document.querySelector('#grade-feedback').value}};const raw=currentAttempt.raw;if(!raw)return showToast('Raw response data is unavailable for this legacy attempt.','warn');const analytics=buildAnalytics({...raw,grades});updateAttempt({grades,analytics});closeModal({resume:false});renderAttempt();});}

function guideQuestionTemplate(){return{questions:[{id:'Q001',type:'mcq',subject:'Quantitative Aptitude',section:'Quantitative Aptitude',topic:'Data Interpretation',passage:'Read the table and answer the question.',table:{role:'prompt',caption:'Sample table',headers:['Item','Value'],rows:[['A','120'],['B','180']]},question:'What is the total value?',options:['200','250','300','350','400'],answer:2,marks:1,negativeMarks:.25,explanation:'120 + 180 = 300.'}]};}
function guideMockTemplate(){return{test:{title:'Quantitative Aptitude Mock 1',description:'Practice test',durationMinutes:20,shuffle:true,questions:guideQuestionTemplate().questions}};}
function pdfToMockPrompt(){return`Convert the attached exam PDF into a JSON mock test for the Prep Studio app.

IMPORTANT OUTPUT RULES
- Return JSON only. Do not add an explanation or Markdown code block.
- Read every question and answer carefully.
- Do not guess a missing answer. Leave out a question if its correct answer is not available.
- Keep all numbers, options, question tables and answer keys exactly as shown in the PDF.
- Never put a solved arrangement, decoded-word table, final answer table, solution diagram or any other answer-revealing content in passage, table or image. Keep those details only in explanation.

USE THIS EXACT STRUCTURE
{
  "test": {
    "title": "Name of the mock test",
    "description": "Short description",
    "durationMinutes": 20,
    "shuffle": true,
    "questions": [
      {
        "id": "Q001",
        "type": "mcq",
        "subject": "Quantitative Aptitude",
        "section": "Quantitative Aptitude",
        "topic": "Data Interpretation",
        "setId": "DI-SET-01",
        "difficulty": "Prelims",
        "passage": "Directions or shared information",
        "table": {
          "role": "prompt",
          "caption": "Table title",
          "headers": ["Column 1", "Column 2"],
          "rows": [["Value 1", "Value 2"]]
        },
        "question": "Question text",
        "options": ["Option A", "Option B", "Option C", "Option D", "Option E"],
        "answer": 0,
        "marks": 1,
        "negativeMarks": 0.25,
        "explanation": "Clear solution"
      }
    ]
  }
}

QUESTION RULES
- Use "mcq" for multiple-choice questions and "descriptive" for writing questions.
- The answer is a number: 0 means A, 1 means B, 2 means C, 3 means D and 4 means E.
- Give every question a different ID such as Q001, Q002 and Q003.
- For a single-subject mock, use the same subject and section on every question. Put labels such as Data Interpretation, Arithmetic and Simplification in topic, not section.
- Copy shared directions, passages and table data into every question that needs them.
- Give every question from the same DI, puzzle or passage set the same setId. Leave setId out for standalone questions.
- Convert only tables that are part of the question into table.headers and table.rows, and set table.role to "prompt".
- For a graph or chart, copy its exact values into a table when possible. Never invent values that are not visible.
- Remove the table field when a question does not need a table.
- For descriptive questions, use an empty options array, answer null, negativeMarks 0, and include modelAnswer, wordLimit and rubric.
- Check that each answer number matches the correct option before returning the JSON.`;}
function repairMockPrompt(){return`Change the JSON pasted below into the standard Prep Studio mock-test format.

Return JSON only. Do not add an explanation or Markdown code block.

Rules:
1. Put everything inside a test object with title, description, durationMinutes, shuffle and questions.
2. Make options an array in A-to-E order.
3. Change letter answers to numbers: a=0, b=1, c=2, d=3, e=4.
4. Use only "mcq" or "descriptive" in the type field.
5. Use one common section name for a single-subject exam. Move labels such as DI, Arithmetic, Simplification and Number Series into topic.
6. Keep shared directions and tables with every question that uses them.
7. Give questions from the same DI, puzzle or passage set the same setId. Remove setId from standalone questions.
8. Remove solved arrangements, decoded-word tables, final-answer tables and solution diagrams from question passage, table and image. Keep them only in explanation.
9. Convert a real question-data table into table.headers and table.rows and set table.role to "prompt".
10. Give every question a unique ID.
11. Keep the original question, options, numbers, correct answer and explanation. Do not invent missing information.
12. Check every answer after conversion.

JSON TO FIX:
[PASTE YOUR JSON HERE]`;}
function renderGuide(){const questionJSON=JSON.stringify(guideQuestionTemplate(),null,2);const mockJSON=JSON.stringify(guideMockTemplate(),null,2);const pdfPrompt=pdfToMockPrompt();const repairPrompt=repairMockPrompt();shell('User Guide',`<div class="guide-layout"><aside class="guide-toc"><b>Help topics</b><a href="#guide-start">Start here</a><a href="#guide-question-json">Question file</a><a href="#guide-mock-json">Mock-test file</a><a href="#guide-pdf-prompt">Convert a PDF with AI</a><a href="#guide-repair-prompt">Fix another JSON format</a><a href="#guide-import">Import files</a><a href="#guide-progress">Improve weak areas</a><a href="#guide-ai">Connect an AI model</a><a href="#guide-data">Save your data</a></aside><article class="guide-content"><section id="guide-start" class="guide-hero"><span class="eyebrow">Start here</span><h2>Prep Studio is simple to use</h2><p>You can practise with the built-in questions, add your own questions, or import a complete mock test.</p><div class="simple-steps"><div><b>1</b><span><strong>Add questions</strong>Import a JSON file or type a question yourself.</span></div><div><b>2</b><span><strong>Take a test</strong>Open Practice, choose a mock and start.</span></div><div><b>3</b><span><strong>Check mistakes</strong>Open History to see your answers, correct answers and time.</span></div><div><b>4</b><span><strong>Ask AI</strong>Connect a model only if you want AI help.</span></div></div><div class="guide-actions"><button class="btn primary" data-view="tests">Open Practice</button><button class="btn" data-view="bank">Open Questions</button></div></section><section id="guide-question-json"><span class="eyebrow">Add questions</span><h2>Make a question JSON file</h2><p>A JSON file is a normal text file that ends with <code>.json</code>. Use the example below as your starting point.</p><div class="plain-note"><b>How the answer number works</b><span>0 = A, 1 = B, 2 = C, 3 = D and 4 = E.</span></div><pre><code>${escapeHTML(questionJSON)}</code></pre><div class="guide-actions"><button class="btn" data-action="download-question-template">Download example</button><button class="btn" data-action="copy-question-template">Copy example</button></div><h3>Questions with tables or pictures</h3><p>Put table headings in <code>headers</code> and each line of data in <code>rows</code>. For a picture or diagram, add an <code>image</code> object with <code>src</code>, <code>alt</code> and <code>caption</code>.</p></section><section id="guide-mock-json"><span class="eyebrow">Add a full mock</span><h2>Make a mock-test JSON file</h2><p>This file creates the questions and the mock test at the same time. Change the title and time before you import it.</p><pre><code>${escapeHTML(mockJSON)}</code></pre><div class="guide-actions"><button class="btn" data-action="download-mock-template">Download example</button><button class="btn" data-action="copy-mock-template">Copy example</button></div><div class="plain-note"><b>For a real exam pattern</b><span>Keep one section name for the subject. Use topic for DI, Arithmetic, Simplification and other question groups. Keep shuffle set to true.</span></div></section><section id="guide-pdf-prompt" class="prompt-guide"><span class="eyebrow">Ready-to-use AI prompt</span><h2>Convert an exam PDF into app-ready JSON</h2><ol><li>Open an AI tool that can read PDF files.</li><li>Upload your exam PDF.</li><li>Copy the prompt below and send it with the PDF.</li><li>Save the AI answer as a file ending in <code>.json</code>.</li><li>Import that file from Practice.</li></ol><pre><code>${escapeHTML(pdfPrompt)}</code></pre><button class="btn primary" data-action="copy-pdf-prompt">Copy PDF conversion prompt</button></section><section id="guide-repair-prompt" class="prompt-guide"><span class="eyebrow">Ready-to-use AI prompt</span><h2>Fix a JSON file that uses another format</h2><p>Use this when you already have JSON, but Prep Studio shows an error or creates the wrong sections.</p><ol><li>Copy the prompt.</li><li>Replace <b>[PASTE YOUR JSON HERE]</b> with your JSON.</li><li>Send it to an AI tool.</li><li>Save the corrected answer as a new <code>.json</code> file.</li></ol><pre><code>${escapeHTML(repairPrompt)}</code></pre><button class="btn primary" data-action="copy-repair-prompt">Copy JSON repair prompt</button></section><section id="guide-import"><span class="eyebrow">Build or import</span><h2>Create your own mock</h2><div class="plain-note"><b>Use questions already in the app</b><span>Open Practice, choose a subject, and then create a test. Choose chapters for random questions, or choose exact questions yourself. Enter the test name and time, then press Create mock.</span></div><h3>Import a file instead</h3><div class="simple-choice"><div><h3>Only add questions</h3><p>Open <b>Questions</b>, choose <b>Import JSON</b>, and select your question file.</p></div><div><h3>Add a complete mock</h3><p>Open <b>Practice</b>, choose the subject, and find <b>Import a mock</b>. Choose Prelims, Mains or Practice, set the time if needed, select your file, and press <b>Import mock test</b>.</p></div></div><div class="plain-note warn"><b>Check before practising</b><span>Open a few questions and confirm the options, answer keys, tables and explanations are correct.</span></div></section><section id="guide-progress"><span class="eyebrow">Improve each subject</span><h2>Use Trends and Mistakes</h2><div class="simple-choice"><div><h3>Performance trend</h3><p>Open History and choose a subject. Choose a graph for marks, correct answers, wrong answers, skipped questions or accuracy. Press All graphs to see every color-coded chart together. Separate averages show the time spent on correct, wrong and skipped questions.</p></div><div><h3>Mistake Notebook</h3><p>Wrong and skipped questions are added automatically. Review the answer, add a note, mark a question mastered, or create a retry test.</p></div></div><div class="plain-note"><b>Ask AI about one mistake</b><span>While reviewing a completed test, press Ask AI about this question. The first analysis sends the full mock once. Later questions reuse a smaller saved summary and your earlier coaching history. All analysed questions stay in one chat so the coach can find repeated patterns.</span></div><div class="plain-note"><b>DI and puzzle sets stay together</b><span>Questions with the same set ID move as one group when the app mixes the test order.</span></div><button class="btn primary" data-view="mistakes">Open Mistake Notebook</button></section><section id="guide-ai"><span class="eyebrow">Optional AI</span><h2>Connect an AI model</h2><ol><li>Open <b>Import & AI</b>.</li><li>Press <b>Add connection</b>.</li><li>Enter a simple name, such as My AI.</li><li>Choose the API format shown in your AI platform's help page.</li><li>Paste the API URL and model ID.</li><li>Choose the correct key type and enter your API key.</li><li>Tick <b>Remember this key</b> only on your own computer.</li><li>Press <b>Save connection</b>, then <b>Test connection</b>.</li></ol><div class="plain-note warn"><b>If the connection fails</b><span>The AI platform must allow browser access, also called CORS. The URL, model ID and key type must exactly match its instructions.</span></div></section><section id="guide-data"><span class="eyebrow">Your data</span><h2>Save your work</h2><ul><li>Questions, mocks, results and chat history stay in this browser.</li><li>Use <b>Export backup</b> often so you do not lose your work.</li><li>API keys are never included in backups.</li><li>A remembered API key stays in this app's browser storage. Do not use this option on a shared or public computer.</li><li>Press <b>Remove saved key</b> before another person uses your browser profile.</li></ul><button class="btn primary" data-action="guide-backup">Export backup now</button></section></article></div>`);bindGuide();}
function bindGuide(){const copy=async(value,message)=>{try{await copyText(typeof value==='string'?value:JSON.stringify(value,null,2));showToast(message,'good');}catch{showToast('Copy failed. Select the text and copy it manually.','warn');}};document.querySelector('[data-action="download-question-template"]').addEventListener('click',()=>downloadJSON('question-bank-template.json',guideQuestionTemplate()));document.querySelector('[data-action="download-mock-template"]').addEventListener('click',()=>downloadJSON('mock-test-template.json',guideMockTemplate()));document.querySelector('[data-action="copy-question-template"]').addEventListener('click',()=>copy(guideQuestionTemplate(),'Question example copied.'));document.querySelector('[data-action="copy-mock-template"]').addEventListener('click',()=>copy(guideMockTemplate(),'Mock-test example copied.'));document.querySelector('[data-action="copy-pdf-prompt"]').addEventListener('click',()=>copy(pdfToMockPrompt(),'PDF conversion prompt copied.'));document.querySelector('[data-action="copy-repair-prompt"]').addEventListener('click',()=>copy(repairMockPrompt(),'JSON repair prompt copied.'));document.querySelector('[data-action="guide-backup"]').addEventListener('click',exportBackup);}

function renderSettings(){shell('Settings',`<section class="grid-2"><article class="card"><div class="card-head"><h2>Practice defaults</h2></div><div class="card-body"><form id="settings-form" class="form-grid"><div class="field"><label>Default question count</label><input name="count" type="number" min="1" max="500" value="${settings.defaultCount}"></div><div class="field"><label>Default duration (minutes)</label><input name="minutes" type="number" min="1" max="300" value="${settings.defaultMinutes}"></div><div class="field"><label>Theme</label><select name="theme"><option value="light" ${settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${settings.theme==='dark'?'selected':''}>Dark</option></select></div><label style="align-self:end"><input name="shuffle" type="checkbox" ${settings.shuffle?'checked':''}> Randomize questions</label><div class="field full"><button class="btn primary" type="submit">Save settings</button></div></form></div></article><article class="card"><div class="card-head"><h2>Install and use offline</h2></div><div class="card-body"><p class="muted">Use the install button when your browser offers it, or download standalone.html and open it directly. Installed browser apps behave like desktop software and keep local data.</p><div class="toolbar"><button class="btn primary" data-action="install-app" ${deferredInstallPrompt?'':'disabled'}>Install app</button><button class="btn" data-action="download-standalone-info">Windows instructions</button></div></div></article></section><section class="card" style="margin-top:16px"><div class="card-head"><h2>Data management</h2></div><div class="card-body"><div class="toolbar"><button class="btn primary" data-action="export-backup">Export complete backup</button><button class="btn" data-action="import-backup">Import backup</button><button class="btn danger" data-action="clear-history">Delete attempt history</button><button class="btn danger" data-action="reset-app">Reset entire app</button></div><p class="muted" style="font-size:12px">Backups include questions, test definitions, attempts, settings and saved AI feedback. API keys are never included.</p></div></section><section class="card" style="margin-top:16px"><div class="card-head"><h2>Storage and security</h2></div><div class="card-body"><ul class="instructions"><li>Browser-local data can be lost if browser storage is cleared. Export backups regularly.</li><li>API keys are session-only unless you choose Remember this key. Remembered keys stay in this app's browser storage, are excluded from backups, and should be used only on a trusted personal device.</li><li>Keep the repository and backups private if they contain licensed question material.</li><li>Custom AI endpoints must support browser CORS. A future Windows wrapper can remove that browser limitation through a local secure bridge.</li></ul></div></section>`);bindSettings();}
function bindSettings(){document.querySelector('#settings-form').addEventListener('submit',(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);settings={...settings,defaultCount:Number(f.get('count')),defaultMinutes:Number(f.get('minutes')),theme:f.get('theme'),shuffle:f.get('shuffle')==='on'};storage.saveSettings(settings);showToast('Settings saved.','good');renderSettings();});document.querySelector('[data-action="install-app"]').addEventListener('click',async()=>{if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;renderSettings();});document.querySelector('[data-action="download-standalone-info"]').addEventListener('click',()=>alert('Windows options:\n\n1. Download standalone.html and open it in Edge or Chrome.\n2. In the browser menu choose Apps > Install this site as an app when available.\n3. For a future signed .exe, this repository is structured for a lightweight Tauri wrapper.'));document.querySelector('[data-action="export-backup"]').addEventListener('click',exportBackup);document.querySelector('[data-action="import-backup"]').addEventListener('click',()=>backupImport.click());document.querySelector('[data-action="clear-history"]').addEventListener('click',()=>{if(confirm('Delete all attempt history?')){attempts=[];storage.clearAttempts();renderSettings();}});document.querySelector('[data-action="reset-app"]').addEventListener('click',()=>{if(confirm('Reset the question bank, tests, history, settings and model configuration?')){storage.clearAll();location.reload();}});}

function startTest(test){const saved=storage.loadActive();if(saved?.questions?.length&&saved.deadlineAt>Date.now()&&!confirm('Starting a new test replaces your unfinished test. Continue?'))return;const questions=materializeTest(test);if(!questions.length)return showToast('This test has no matching questions.','warn');storage.clearActive();state=freshRuntime();state.screen='exam';state.test=test;state.title=test.title;state.questions=questions;state.startedAt=Date.now();state.durationSeconds=Math.max(60,Number(test.durationMinutes||settings.defaultMinutes)*60);state.deadlineAt=state.startedAt+state.durationSeconds*1000;state.seen[0]=true;state.visits[0]=1;logEvent('start',{testId:test.id});persistActive();renderExam();startTimer();}
function logEvent(type,data={}){state.events.push({type,atMs:Math.max(0,Date.now()-state.startedAt),questionIndex:state.current,...data});}
function startTracking(){if(state.screen==='exam'&&!state.modalOpen&&!document.hidden&&!state.tracking){state.enteredAt=Date.now();state.tracking=true;}}
function pauseTracking(reason='pause'){if(!state.tracking)return;const now=Date.now(),delta=Math.max(0,now-state.enteredAt);state.timeByQuestion[state.current]=(state.timeByQuestion[state.current]||0)+delta;state.tracking=false;logEvent('active-time',{reason,milliseconds:delta});persistActive();}
function activeSnapshot(){const{screen,enteredAt,tracking,modalOpen,...safe}=state;return{...safe,savedAt:Date.now()};}
function persistActive(){if(['exam','submitting'].includes(state.screen)&&!storage.saveActive(activeSnapshot()))warnStorageOnce();}
function restoreActive(saved){if(!saved?.questions?.length||saved.deadlineAt<=Date.now()){storage.clearActive();return false;}state={...freshRuntime(),...saved,questions:migrateStoredBank(saved.questions),screen:'exam',tracking:false,modalOpen:false};state.seen[state.current]=true;state.visits[state.current]=(state.visits[state.current]||0)+1;renderExam();startTimer();return true;}
function startTimer(){clearInterval(timer);const tick=()=>{const left=Math.max(0,Math.ceil((state.deadlineAt-Date.now())/1000));document.querySelector('#timer')?.replaceChildren(document.createTextNode(formatTime(left)));if(left<=0&&state.screen==='exam')finishAttempt(true);};tick();timer=setInterval(tick,1000);}
function examSections(){return unique(state.questions.map(q=>q.section||q.subject));}
function sectionIndices(section){return state.questions.map((q,i)=>(q.section||q.subject)===section?i:-1).filter(i=>i>=0);}
function qStatus(i){if(state.marked[i]&&hasAnswer(i))return'answeredmarked';if(state.marked[i])return'marked';if(hasAnswer(i))return'answered';if(state.seen[i])return'notanswered';return'notvisited';}
function hasAnswer(i){const q=state.questions[i],value=state.answers[i];return q?.type==='descriptive'?Boolean(String(value||'').trim()):value!==undefined&&value!==null;}
function statusCounts(indices){const c={notvisited:0,notanswered:0,answered:0,marked:0,answeredmarked:0};indices.forEach(i=>c[qStatus(i)]++);return c;}
function renderExam(){const q=state.questions[state.current];if(!q)return navigate('dashboard');state.screen='exam';document.body.classList.remove('tutor-view');state.seen[state.current]=true;const section=q.section||q.subject,indices=sectionIndices(section),c=statusCounts(indices),left=Math.max(0,Math.ceil((state.deadlineAt-Date.now())/1000));const tabs=examSections().map(name=>`<button class="section-tab ${name===section?'active':''}" data-section="${escapeHTML(name)}">${escapeHTML(name)}</button>`).join('');const response=q.type==='descriptive'?`<textarea id="descriptive-response" class="descriptive-answer" placeholder="Write your response here…">${escapeHTML(state.answers[state.current]||'')}</textarea><div class="word-count"><span id="word-count">${wordCount(state.answers[state.current])}</span>${q.wordLimit?` / ${q.wordLimit}`:''} words</div>`:q.options.map((option,i)=>`<label class="option ${state.answers[state.current]===i?'selected':''}"><input type="radio" name="answer" value="${i}" ${state.answers[state.current]===i?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${escapeHTML(option)}</span></label>`).join('');const palette=indices.map(i=>`<button class="qn ${qStatus(i)} ${i===state.current?'current':''}" data-question="${i}">${i+1}</button>`).join('');app.innerHTML=`<main class="cbt"><header class="cbt-head"><div class="exam-title"><div class="exam-seal">PO</div><div><b>${escapeHTML(state.title)}</b><small>${q.type==='descriptive'?'Descriptive':'Objective'} exam · independent simulator</small></div></div><div class="clock"><span>Time Left</span><strong id="timer">${formatTime(left)}</strong></div></header><nav class="section-tabs">${tabs}</nav><div class="workspace"><section class="question-pane"><div class="q-meta"><b>Question No. ${state.current+1}</b><span>Marks: <b class="ok">${q.marks||0}</b>${q.type!=='descriptive'?` &nbsp; Negative: <b class="bad">${q.negativeMarks||0}</b>`:''}</span><span>${escapeHTML(q.subject)} · ${escapeHTML(q.topic)}</span></div><div class="q-content">${renderQuestionMedia(q)}<div class="question-text">${escapeHTML(q.question)}</div>${response}</div><div class="exam-actions"><div class="button-group"><button class="btn purple" data-action="mark-next">${state.current===state.questions.length-1?'Mark for Review':'Mark for Review &amp; Next'}</button><button class="btn" data-action="clear-response">Clear Response</button></div><button class="btn primary" data-action="save-next">${state.current===state.questions.length-1?'Review & Submit':'Save &amp; Next'}</button></div></section><aside class="side"><div class="candidate"><div class="avatar"></div><div><b>Candidate</b><small>Private practice session</small></div></div><div class="palette-head">Question Palette</div><div class="palette-body"><h4>${escapeHTML(section)}</h4><div class="q-grid">${palette}</div>${examLegend(c)}<p class="muted" style="font-size:10px">Orange outline shows the current item.</p></div></aside></div><footer class="exam-foot"><div class="button-group"><button class="btn small" data-action="question-paper">Question Paper</button><button class="btn small" data-action="instructions">Instructions</button></div><button class="btn orange" data-action="submit">Submit</button></footer></main>`;bindExam();startTracking();}
function examLegend(c){return`<div class="legend"><div class="legend-item"><span class="shape">${c.notvisited}</span>Not Visited</div><div class="legend-item"><span class="shape red">${c.notanswered}</span>Not Answered</div><div class="legend-item"><span class="shape green">${c.answered}</span>Answered</div><div class="legend-item"><span class="shape purple">${c.marked}</span>Marked</div><div class="legend-item" style="grid-column:1/3"><span class="shape purple tick">${c.answeredmarked}</span>Answered &amp; Marked</div></div>`;}
function moveTo(index){pauseTracking('navigate');state.current=Math.max(0,Math.min(state.questions.length-1,index));state.seen[state.current]=true;state.visits[state.current]=(state.visits[state.current]||0)+1;logEvent('visit-question');persistActive();renderExam();}
function bindExam(){document.querySelectorAll('input[name="answer"]').forEach(r=>r.addEventListener('change',()=>{pauseTracking('answer');const next=Number(r.value),previous=state.answers[state.current];if(previous!==undefined&&previous!==next)state.answerChanges[state.current]=(state.answerChanges[state.current]||0)+1;state.answers[state.current]=next;logEvent('answer',{selected:next});persistActive();renderExam();}));const textarea=document.querySelector('#descriptive-response');if(textarea){textarea.addEventListener('input',()=>{state.answers[state.current]=textarea.value;document.querySelector('#word-count').textContent=wordCount(textarea.value);persistActive();});textarea.addEventListener('change',()=>logEvent('descriptive-save',{words:wordCount(textarea.value)}));}document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>moveTo(Number(b.dataset.question))));document.querySelectorAll('[data-section]').forEach(b=>b.addEventListener('click',()=>moveTo(sectionIndices(b.dataset.section)[0])));document.querySelector('[data-action="clear-response"]').addEventListener('click',()=>{pauseTracking('clear');if(hasAnswer(state.current))state.answerChanges[state.current]=(state.answerChanges[state.current]||0)+1;delete state.answers[state.current];persistActive();renderExam();});document.querySelector('[data-action="save-next"]').addEventListener('click',()=>{if(state.current===state.questions.length-1)showSubmit();else moveTo(state.current+1);});document.querySelector('[data-action="mark-next"]').addEventListener('click',()=>{state.marked[state.current]=true;persistActive();if(state.current===state.questions.length-1)showSubmit();else moveTo(state.current+1);});document.querySelector('[data-action="submit"]').addEventListener('click',showSubmit);document.querySelector('[data-action="instructions"]').addEventListener('click',showInstructions);document.querySelector('[data-action="question-paper"]').addEventListener('click',showQuestionPaper);}
function openModal(content){pauseTracking('modal');state.modalOpen=true;const shade=document.createElement('div');shade.className='shade';shade.id='modal-shade';shade.innerHTML=`<section class="modal">${content}</section>`;document.body.append(shade);shade.addEventListener('click',e=>{if(e.target===shade)closeModal();});shade.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal()));}
function closeModal({resume=true}={}){document.querySelector('#modal-shade')?.remove();state.modalOpen=false;if(resume&&state.screen==='exam')startTracking();}
function showInstructions(){openModal(`<div class="modal-head"><span>Instructions</span><button class="btn small" data-close>Close</button></div><div class="modal-body instructions"><ol><li>The countdown runs continuously and auto-submits at zero.</li><li>Objective questions use their displayed marks and negative marks.</li><li>Descriptive responses are saved locally and require AI or manual grading.</li><li>Active time excludes instructions, question-paper and submit dialogs, and hidden browser tabs.</li><li>Save &amp; Next, Mark for Review &amp; Next and the palette preserve every response.</li></ol></div><div class="modal-actions"><button class="btn primary" data-close>Close</button></div>`);}
function showQuestionPaper(){openModal(`<div class="modal-head"><span>Question Paper</span><button class="btn small" data-close>Close</button></div><div class="modal-body" style="max-height:65vh;overflow:auto">${state.questions.map((q,i)=>`<button class="nav-btn" style="width:100%;color:var(--ink)" data-paper="${i}"><b>Q${i+1}.</b> ${escapeHTML(q.question).slice(0,180)}</button>`).join('')}</div>`);document.querySelectorAll('[data-paper]').forEach(b=>b.addEventListener('click',()=>{closeModal({resume:false});moveTo(Number(b.dataset.paper));}));}
function showSubmit(){const rows=examSections().map(section=>{const ids=sectionIndices(section),c=statusCounts(ids);return`<tr><td>${escapeHTML(section)}</td><td>${ids.length}</td><td>${c.answered+c.answeredmarked}</td><td>${c.notanswered}</td><td>${c.marked+c.answeredmarked}</td><td>${c.notvisited}</td></tr>`;}).join('');openModal(`<div class="modal-head"><span>Submit test</span><button class="btn small" data-close>Close</button></div><div class="modal-body"><p>Review your response status.</p><div class="table-wrap"><table class="table"><tr><th>Section</th><th>Total</th><th>Answered</th><th>Not answered</th><th>Marked</th><th>Not visited</th></tr>${rows}</table></div><p><b>Are you sure you want to submit?</b></p></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn orange" id="confirm-submit">Confirm Submit</button></div>`);document.querySelector('#confirm-submit').addEventListener('click',()=>finishAttempt(false));}
function finishAttempt(autoSubmitted){if(state.screen!=='exam')return;pauseTracking('submit');state.screen='submitting';closeModal({resume:false});clearInterval(timer);state.screen='results';const raw={questions:state.questions,answers:state.answers,timeByQuestion:state.timeByQuestion,visits:state.visits,answerChanges:state.answerChanges,marked:state.marked};const analytics=buildAnalytics({...raw,grades:{}});const attempt={id:uid('attempt'),title:state.title,testId:state.test?.id,completedAt:new Date().toISOString(),startedAt:new Date(state.startedAt).toISOString(),elapsedSeconds:Math.round((Date.now()-state.startedAt)/1000),autoSubmitted,isTestRun:false,raw,grades:{},analytics,aiNotes:''};attempts=[attempt,...attempts].slice(0,MAX_ATTEMPTS);if(!storage.saveAttempts(attempts))warnStorageOnce();storage.clearActive();currentAttempt=attempt;renderAttempt();}

async function copyText(text){if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(text);const a=document.createElement('textarea');a.value=text;a.style.cssText='position:fixed;opacity:0';document.body.append(a);a.select();document.execCommand('copy');a.remove();}
function exportBackup(){downloadJSON(`prep-studio-backup-${new Date().toISOString().slice(0,10)}.json`,storage.exportAll());}
async function readJSONFile(file){if(!file||file.size>20*1024*1024)throw new Error('Choose a JSON file smaller than 20 MB.');return JSON.parse(await file.text());}
function safeBackupId(value,prefix){const id=String(value||'').trim();return/^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$/.test(id)?id:uid(prefix);}
function prepareBackup(backup){
  if(![1,2,3].includes(backup?.schemaVersion))throw new Error('Unsupported backup format.');
  if(backup.attempts!==undefined&&!Array.isArray(backup.attempts))throw new Error('Backup attempts must be a list.');
  if(backup.tests!==undefined&&!Array.isArray(backup.tests))throw new Error('Backup tests must be a list.');
  if(backup.aiProfiles!==undefined&&!Array.isArray(backup.aiProfiles))throw new Error('Backup AI profiles must be a list.');
  if(backup.tutorChats!==undefined&&!Array.isArray(backup.tutorChats))throw new Error('Backup Tutor chats must be a list.');
  if(backup.settings!==undefined&&(!backup.settings||Array.isArray(backup.settings)||typeof backup.settings!=='object'))throw new Error('Backup settings are not valid. Nothing was restored.');
  if(backup.settings?.customCatalog!==undefined&&(!Array.isArray(backup.settings.customCatalog)||backup.settings.customCatalog.some(item=>!item||typeof item.subject!=='string'||!Array.isArray(item.chapters))))throw new Error('Backup subject list is not valid.');
  for(const attempt of backup.attempts||[]){
    if(!attempt||typeof attempt!=='object'||Array.isArray(attempt))throw new Error('Backup contains an invalid attempt.');
    if(attempt.raw){if(!Array.isArray(attempt.raw.questions))throw new Error('Backup attempt questions must be a list.');normalizeImportedBank(attempt.raw.questions);}
    if(attempt.analytics?.rows!==undefined&&(!Array.isArray(attempt.analytics.rows)||attempt.analytics.rows.some(row=>!row?.question||!Array.isArray(row.question.options))))throw new Error('Backup attempt review data is not valid.');
  }
  for(const chat of backup.tutorChats||[])if(!chat||!Array.isArray(chat.messages))throw new Error('Backup chat messages must be a list.');
  const nextBank=backup.bank?migrateStoredBank(normalizeImportedBank(backup.bank)):starterBank;
  const bankIds=new Set(nextBank.map(question=>question.id));
  const nextTests=(backup.tests||[]).filter(item=>item&&typeof item==='object').map(item=>({...item,id:safeBackupId(item.id,'test'),title:String(item.title||'Restored test').slice(0,120),description:String(item.description||'').slice(0,300),questionIds:Array.isArray(item.questionIds)?item.questionIds.map(String).filter(id=>bankIds.has(id)):undefined,subjects:Array.isArray(item.subjects)?item.subjects.map(String):[],topics:Array.isArray(item.topics)?item.topics.map(String):[],types:Array.isArray(item.types)?item.types.filter(type=>['mcq','descriptive'].includes(type)):['mcq'],count:Math.max(1,Math.min(1000,Number(item.count)||1)),durationMinutes:Math.max(1,Math.min(600,Number(item.durationMinutes)||settings.defaultMinutes))}));
  const nextAttempts=migrateAttempts(backup.attempts||[]).map(item=>({...item,id:safeBackupId(item.id,'attempt'),title:String(item.title||'Restored attempt').slice(0,120)})).slice(0,MAX_ATTEMPTS);
  const nextSettings=backup.settings&&typeof backup.settings==='object'?{...settings,...backup.settings,theme:backup.settings.theme==='dark'?'dark':'light',defaultCount:Math.max(1,Math.min(500,Number(backup.settings.defaultCount)||settings.defaultCount)),defaultMinutes:Math.max(1,Math.min(300,Number(backup.settings.defaultMinutes)||settings.defaultMinutes)),shuffle:backup.settings.shuffle!==false}:{...settings};
  const nextProfiles=Array.isArray(backup.aiProfiles)&&backup.aiProfiles.length?backup.aiProfiles.filter(item=>item&&typeof item==='object').map(item=>({...sanitizeAIConfig(item),id:safeBackupId(item.id,'profile'),name:String(item.name||'Restored connection').slice(0,100)})):aiProfiles;
  if(!nextProfiles.length)throw new Error('Backup contains no valid AI connection profiles.');
  const legacyChat=Array.isArray(backup.tutor)&&backup.tutor.length?[{id:uid('chat'),title:'Restored conversation',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),messages:backup.tutor}]:[];
  const nextChats=(Array.isArray(backup.tutorChats)&&backup.tutorChats.length?backup.tutorChats:legacyChat).filter(item=>item&&typeof item==='object').map(item=>({...item,id:safeBackupId(item.id,'chat'),title:String(item.title||'Restored chat').slice(0,120),messages:(Array.isArray(item.messages)?item.messages:[]).filter(message=>message&&typeof message.content==='string').map(message=>({...message,role:message.role==='user'?'user':'assistant',content:message.content.slice(0,100000)})).slice(-120)}));
  return{bank:nextBank,attempts:nextAttempts,tests:nextTests,settings:nextSettings,profiles:nextProfiles,chats:nextChats.length?nextChats:tutorChats,mistakes:backup.mistakeState&&typeof backup.mistakeState==='object'?backup.mistakeState:{}};
}
questionImport.addEventListener('change',async()=>{try{const imported=normalizeImportedBank(await readJSONFile(questionImport.files[0]));const overlap=imported.filter(q=>bank.some(existing=>existing.id===q.id)).length;if(overlap&&!confirm(`${overlap} existing questions have matching IDs and will be updated. Continue?`))return;const map=new Map(bank.map(q=>[q.id,q]));imported.forEach(q=>map.set(q.id,q));bank=[...map.values()];storage.saveBank(bank);showToast(`Imported ${imported.length} questions. Bank total: ${bank.length}.`,'good');renderView();}catch(error){showToast(error.message,'warn');}questionImport.value='';});
backupImport.addEventListener('change',async()=>{try{const prepared=prepareBackup(await readJSONFile(backupImport.files[0]));if(!confirm('Replace local bank, tests, history and settings with this backup? Saved API keys will be removed for safety; reconnect AI afterwards.'))return;bank=prepared.bank;attempts=prepared.attempts;customTests=prepared.tests;settings=prepared.settings;aiProfiles=prepared.profiles;activeProfileId=aiProfiles.some(profile=>profile.id===settings.activeAIProfileId)?settings.activeAIProfileId:aiProfiles[0].id;aiConfig=aiProfiles.find(profile=>profile.id===activeProfileId)||aiProfiles[0];rememberedKeys={};storage.clearAIKeys();sessionKeys.clear();sessionApiKey='';tutorChats=prepared.chats;activeTutorChatId=tutorChats[0].id;tutorMessages=tutorChats[0].messages.slice(-100);settings.activeTutorChatId=activeTutorChatId;mistakeState=prepared.mistakes;saveCore();storage.clearActive();showToast('Backup restored.','good');renderView();}catch(error){showToast(error.message,'warn');}backupImport.value='';});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;});document.addEventListener('visibilitychange',()=>document.hidden?pauseTracking('tab-hidden'):startTracking());window.addEventListener('pagehide',()=>pauseTracking('pagehide'));window.addEventListener('beforeunload',()=>pauseTracking('beforeunload'));window.addEventListener('error',e=>{console.error(e.error||e.message);if(!app.children.length)app.innerHTML=`<div class="fatal"><b>The app encountered an error.</b><br>${escapeHTML(e.message)}<br>Your active test is stored locally.</div>`;});if('serviceWorker'in navigator&&location.protocol.startsWith('http')){try{navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch{}}
renderView();
